import React from 'react';
import {Navigate} from 'react-router-dom';
import {magic, ROUTES} from '@utils';
import {Input, Button} from '@ui';
import woody from '@styles/images/woody.png'
import s from './style.scss';

const AuthPage = ({code, setCode, checkCode, isValidCode, user, loading}) => {
  if (user) {
    return <Navigate to={ROUTES.MAIN} />;
  }

  return (
    <div className={s.page}>
      <div className={s.container}>
        <p className={s.welcomeText}>
          {'Добро пожаловать в мой список желаний!'}
        </p>
        <Input
          value={code}
          onChange={setCode}
          placeholder={'Введите код приглашения'}
        />
        <div className={s.button}>
          <Button
            type={'button'}
            onClick={checkCode}
            disabled={loading || !isValidCode}
            color={'yellow'}
          >
            {'Войти'}
          </Button>
        </div>
        <img
          className={s.picture}
          src={woody}
          alt={'woody'}
        />
      </div>
    </div>
  );
};

const mapStore = ({UserStore}) => {
  return {
    code: UserStore.code,
    setCode: UserStore.setCode,
    checkCode: UserStore.checkCode,
    isValidCode: UserStore.isValidCode,
    user: UserStore.user,
    loading: UserStore.loading
  };
};

export default magic(AuthPage, {store: mapStore, styles: s});