import {makeObservable, observable, action, computed} from 'mobx';
import {onAuthStateChanged, signOut} from 'firebase/auth';
import {signIn, signUp} from '@api';
import {auth} from '../firebase';
import {notify} from '@utils';
import {User} from '@firebase/auth';

// облегченная система авторизации
const codes = [
  '0666B7C0B1',
  '44C5EB01C3',
  'C2026F65F4',
  'FD15FCFD9B',
  '3BC12ECCC1',
  '96A26F7688',
  '8CA69447C5',
  '1D4D13BBD4',
  '83E95173FA',
  '438177195A',
  '542E67D5C7',
  'C6516B78AE',
  '7626B88BA7',
  'B79A9634A4',
  'D7CEC202C7',
  '525DDFE503',
  '187573A7E6',
  '0F4C42BCA1',
  'FFB1090DF7',
  '2AC3489B48',
  'C383923BD9',
  '0BE37B45A8',
  '8B4E101E02',
  'A7AACEB219',
  '5078851294'
];

export default class UserStore {
  code: string = '';
  user: User | null = null;
  loading: boolean = true;

  constructor() {
    makeObservable(this, {
      code: observable,
      user: observable,
      loading: observable,

      isValidCode: computed,

      setCode: action,
      setUser: action,
      setLoading: action
    });

    signUp(`archycoon@ya.ru`, `100enot500`)

    // для создания учёток
    // for (const code of codes) {
    //   try {
    //     signUp(`${code}@mail.com`, `pass${code}`)
    //   } catch(err) {
    //     console.log(err);
    //   }
    // }
  }

  get isValidCode() {
    return this.code.length === 10;
  }

  setCode = ({target}) => {
    this.code = target.value;
  };

  setUser = (user: User | null) => {
    this.user = user;
  };

  setLoading = (state: boolean) => {
    this.loading = state;
  };

  checkCode = async() => {
    const correctCode = codes.find((code) => code === this.code);

    if (!correctCode) {
      return notify({
        variant: 'error',
        message: `Введён неверный код`
      });
    }

    this.setLoading(true);

    try {
      const user = await signIn(`${correctCode}@mail.com`, `pass${correctCode}`);

      this.setUser(user);
    } catch(err) {
      notify({
        variant: 'error',
        message: `Что-то пошло не так! Обратитесь к администратору`
      });
    } finally {
      this.setLoading(false);
    }
  };

  checkAuth = () => {
    onAuthStateChanged(auth, (user) => {
      this.setUser(user);
      this.setLoading(false);

      return user;
    });
  };

  logOut = () => signOut(auth);
}